#!/usr/bin/env node
// Generates each app's typed API description from the services' OpenAPI specs (build plan
// 7.1): backend/openapi/<service>.json → src/api/generated/<service>.ts in frontend/ and
// frontend-app/, with openapi-typescript. The apps call the services through openapi-fetch
// clients typed by these files (src/api/services.ts), so a path, a body or a response that
// changes in a spec fails the apps' typecheck.
//
//   node scripts/sync-api-clients.mjs          rewrite the generated files
//   node scripts/sync-api-clients.mjs --check  exit 1 if any is stale (CI)
//
// Needs frontend/node_modules (openapi-typescript is a dev dependency there).

import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SPECS = 'backend/openapi';
const APPS = ['frontend', 'frontend-app'];
const OUTPUT = 'src/api/generated';
const CHECK = process.argv.includes('--check');

const require = createRequire(path.join(ROOT, 'frontend', 'package.json'));
let openapiTS;
let astToString;
try {
  // Resolved from frontend/, which gives the CommonJS build: its exports sit on `default`.
  const mod = await import(pathToFileURL(require.resolve('openapi-typescript')).href);
  const api = mod.default ?? mod;
  openapiTS = api.default ?? api;
  astToString = api.astToString ?? mod.astToString;
} catch (err) {
  console.error(`openapi-typescript not found (run npm ci in frontend/): ${err.message}`);
  process.exit(1);
}

const services = fs
  .readdirSync(path.join(ROOT, SPECS))
  .filter((name) => name.endsWith('.json'))
  .map((name) => name.slice(0, -'.json'.length))
  .sort();

async function render(service) {
  const spec = JSON.parse(fs.readFileSync(path.join(ROOT, SPECS, `${service}.json`), 'utf8'));
  const ast = await openapiTS(spec);
  return [
    `// Generated by scripts/sync-api-clients.mjs from ${SPECS}/${service}.json — do not edit.`,
    '// Run `node scripts/sync-api-clients.mjs` after the spec changes.',
    '',
    astToString(ast),
  ].join('\n');
}

// Compares (and, unless --check, rewrites) a file through one file descriptor, as
// scripts/sync-gateway.mjs does (CWE-367).
function syncFile(file, content) {
  if (!CHECK) fs.mkdirSync(path.dirname(file), { recursive: true });
  let fd;
  try {
    fd = fs.openSync(file, CHECK ? 'r' : fs.constants.O_RDWR | fs.constants.O_CREAT);
  } catch (err) {
    if (CHECK && err.code === 'ENOENT') return true; // missing counts as stale
    throw err;
  }
  try {
    if (fs.readFileSync(fd, 'utf8') === content) return false;
    if (!CHECK) {
      fs.ftruncateSync(fd, 0);
      fs.writeSync(fd, content, 0, 'utf8');
    }
    return true;
  } finally {
    fs.closeSync(fd);
  }
}

const stale = [];
for (const service of services) {
  const content = await render(service);
  for (const app of APPS) {
    const relative = path.join(app, OUTPUT, `${service}.ts`);
    if (syncFile(path.join(ROOT, relative), content)) stale.push(relative);
  }
}
// A generated file whose spec is gone is stale too (removed, unless --check).
const wanted = new Set(services.map((service) => `${service}.ts`));
for (const app of APPS) {
  const dir = path.join(ROOT, app, OUTPUT);
  if (!fs.existsSync(dir)) continue;
  for (const name of fs.readdirSync(dir)) {
    if (!name.endsWith('.ts') || wanted.has(name)) continue;
    stale.push(path.join(app, OUTPUT, name));
    if (!CHECK) fs.rmSync(path.join(dir, name));
  }
}

if (CHECK && stale.length) {
  console.error(`Stale generated API files (run \`node scripts/sync-api-clients.mjs\`):\n  ${stale.join('\n  ')}`);
  process.exit(1);
}
console.log(
  stale.length
    ? `Updated:\n  ${stale.join('\n  ')}`
    : `API clients are up to date (${services.length} services, ${APPS.length} apps).`,
);
